def __parallel_queue_worker(worker_id: int, job_queue: multiprocessing.Queue, result_queue: multiprocessing.Queue, worker_fn: Callable[[int, JobType], Iterable[ResultType]]):
    while True:
        job = job_queue.get()
        if job is None:
            job_queue.put(job)
            break
        for result in worker_fn(worker_id, job):
            result_queue.put(result)
    result_queue.put(None)

while True:
    job = job_queue.get()
    if job is None:
        job_queue.put(job)
        break
    for result in worker_fn(worker_id, job):
        result_queue.put(result)

while True:
    result = result_queue.get()
    if result is None:
        num_workers_finished += 1
        if num_workers_finished == len(workers):
            finished_callback()
            break
    else:
        received_result_callback(result)

if job is None:
    job_queue.put(job)
    break

if result is None:
    num_workers_finished += 1
    if num_workers_finished == len(workers):
        finished_callback()
        break
else:
    received_result_callback(result)

